import{_ as l,B as d,o as t,c as r,ax as s,b as i,w as o,a as n,E as h,ah as c}from"./chunks/framework.Bnt0oLax.js";const v=JSON.parse(`{"title":"Stylesheets Overview","description":"How global stylesheets work — where they're injected, how they're scoped, and how they compare to widget styles","frontmatter":{"description":"How global stylesheets work — where they're injected, how they're scoped, and how they compare to widget styles"},"headers":[],"relativePath":"custom-widgets/v2/stylesheets-overview.md","filePath":"custom-widgets/v2/stylesheets-overview.md"}`),y={name:"custom-widgets/v2/stylesheets-overview.md"};function p(g,e,f,m,u,w){const a=d("Mermaid");return t(),r("div",null,[e[1]||(e[1]=s('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/custom-widgets/v2/stylesheets-overview.md for this page in Markdown format</div><h1 id="stylesheets-overview" tabindex="-1">Stylesheets Overview <a class="header-anchor" href="#stylesheets-overview" aria-label="Permalink to &quot;Stylesheets Overview&quot;">​</a></h1><p>Stylesheets are CSS files that apply across your community pages, independent of individual widgets. Use them for shared design tokens, component styles, custom fonts, or any sitewide theming that shouldn&#39;t live inside a single widget.</p><h2 id="how-stylesheets-work" tabindex="-1">How Stylesheets Work <a class="header-anchor" href="#how-stylesheets-work" aria-label="Permalink to &quot;How Stylesheets Work&quot;">​</a></h2><p>Each stylesheet you declare in the <code>stylesheets</code> array of <code>extensions_registry.json</code> becomes a <code>&lt;link rel=&quot;stylesheet&quot;&gt;</code> tag injected into every matching page of your community. The platform publishes the file from your repository (or loads it from an external URL) and inserts the tag at the location you choose.</p>',5)),(t(),i(c,null,{default:o(()=>[h(a,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22stylesheets%2Ftheme%2Fstyle.css%22%5D%20--%3E%20B%5B%22Published%20by%20platform%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22Link%20tag%20injected%20on%20page%20load%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22Styles%20apply%20to%20the%20page%22%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23eef5fc%2Cstroke%3A%2339a2ff%2Ccolor%3A%23132436%0A%20%20%20%20style%20B%20fill%3A%23dbeafe%2Cstroke%3A%233b82f6%2Ccolor%3A%231e293b%0A%20%20%20%20style%20C%20fill%3A%23dbeafe%2Cstroke%3A%233b82f6%2Ccolor%3A%231e293b%0A%20%20%20%20style%20D%20fill%3A%23dcfce7%2Cstroke%3A%2322c55e%2Ccolor%3A%231e293b%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<h2 id="stylesheets-vs-widget-styles" tabindex="-1">Stylesheets vs Widget Styles <a class="header-anchor" href="#stylesheets-vs-widget-styles" aria-label="Permalink to &quot;Stylesheets vs Widget Styles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>Widget styles</th><th>Global stylesheet</th></tr></thead><tbody><tr><td>Scope</td><td>Inside the widget&#39;s Shadow DOM</td><td>The whole page</td></tr><tr><td>Reach</td><td>Only affects the widget&#39;s own markup</td><td>Affects every element on matching pages</td></tr><tr><td>Isolation</td><td>Isolated from the page by Shadow DOM</td><td>Runs directly against page HTML</td></tr><tr><td>Use cases</td><td>A single component&#39;s appearance</td><td>Sitewide theming, fonts, design tokens, cross-page overrides</td></tr></tbody></table><p>Widget styles are scoped and isolated. Global stylesheets reach the whole page and every widget on it — including the community&#39;s own built-in elements.</p><h2 id="where-stylesheets-load" tabindex="-1">Where Stylesheets Load <a class="header-anchor" href="#where-stylesheets-load" aria-label="Permalink to &quot;Where Stylesheets Load&quot;">​</a></h2><p>Stylesheets are injected at one of three locations, controlled by the <code>placement</code> field:</p><table tabindex="0"><thead><tr><th>Placement</th><th>Location</th><th>Use case</th></tr></thead><tbody><tr><td><code>head</code> (default)</td><td>Inside <code>&lt;head&gt;</code></td><td>Fonts, critical styles, anything that must apply before content renders</td></tr><tr><td><code>bodyStart</code></td><td>Start of <code>&lt;body&gt;</code></td><td>Stylesheets that depend on the DOM starting to load</td></tr><tr><td><code>bodyEnd</code></td><td>End of <code>&lt;body&gt;</code></td><td>Non-critical styles loaded after page content</td></tr></tbody></table><h2 id="repository-hosted-vs-external" tabindex="-1">Repository-Hosted vs External <a class="header-anchor" href="#repository-hosted-vs-external" aria-label="Permalink to &quot;Repository-Hosted vs External&quot;">​</a></h2><p>Each stylesheet has a <code>path</code> field. Two shapes are supported:</p><ul><li><strong>Repository path</strong> (e.g. <code>stylesheets/theme/style.css</code>) — the file lives in your repository and the platform publishes it.</li><li><strong>External URL</strong> (e.g. <code>https://fonts.example.com/inter.css</code>) — the tag loads directly from that URL. The platform does not fetch or publish it.</li></ul><h2 id="conditional-loading" tabindex="-1">Conditional Loading <a class="header-anchor" href="#conditional-loading" aria-label="Permalink to &quot;Conditional Loading&quot;">​</a></h2><p>By default, a stylesheet loads on every page of your community. Use the <code>rules</code> field to load a stylesheet only when the current page matches conditions like a specific page type, locale, or authenticated user. See <a href="./page-targeting.html">Page Targeting</a> for the full rule language.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./first-stylesheet.html">Your First Stylesheet</a> — hands-on tutorial from scratch to published stylesheet</li><li><a href="./stylesheets.html">Stylesheet Definition Reference</a> — every field and option</li><li><a href="./page-targeting.html">Page Targeting</a> — conditional loading rules</li><li><a href="./registry-reference.html">Registry Reference</a> — where stylesheets fit in the registry file</li></ul>',13))])}const S=l(y,[["render",p]]);export{v as __pageData,S as default};
